∀ {m d kD : ℕ} {Λ SD : Type} (P : Complexity.LogProg.RProg m d Λ) (l₀ : Λ) (D : Turing.MultiTapeTM kD Bool SD)
  (q0 : Fin d → SD),
  Complexity.LogProg.compileTM P l₀ D q0 = { q₀ := Complexity.LogProg.CSt.prog l₀, tr := Complexity.LogProg.ctr P D q0 }

∀ {m d kD : ℕ} {Λ SD : Type} (P : Complexity.LogProg.RProg m d Λ) (D : Turing.MultiTapeTM kD Bool SD) (q0 : Fin d → SD)
  (x : Option Bool) (x_1 : Fin (m + kD) → Option Bool) (l : Λ) (s : Fin (m + 1)) (dir res : Bool) (a : Fin m)
  (scan : Bool),
  Complexity.LogProg.ctr P D q0 (Complexity.LogProg.CSt.retR l s dir res a scan) x x_1 =
    match P.call l with
    | none => { inputTape := 0, workTapes := fun x => (none, 0), output := none, state := none }
    | some cs =>
      have r := cs.args.getD (↑a) a;
      have rd := x_1 (Fin.castAdd kD r);
      have leftSide := decide (↑s < ↑a + 1) || decide (↑s = ↑a + 1) && !dir;
      if scan = true then
        match rd with
        | some val =>
          { inputTape := 0, workTapes := Fin.append (Complexity.LogProg.regMove r (-1)) Complexity.LogProg.dIdle,
            output := none, state := some (Complexity.LogProg.CSt.retR l s dir res a true) }
        | none =>
          { inputTape := 0, workTapes := Fin.append (Complexity.LogProg.regMove r 1) Complexity.LogProg.dIdle,
            output := none, state := some (Complexity.LogProg.nextRet cs l s dir res (↑a + 1)) }
      else
        match rd with
        | none =>
          if leftSide = true then
            { inputTape := 0, workTapes := Fin.append (Complexity.LogProg.regMove r 1) Complexity.LogProg.dIdle,
              output := none, state := some (Complexity.LogProg.nextRet cs l s dir res (↑a + 1)) }
          else
            { inputTape := 0, workTapes := Fin.append (Complexity.LogProg.regMove r (-1)) Complexity.LogProg.dIdle,
              output := none, state := some (Complexity.LogProg.CSt.retR l s dir res a true) }
        | some val =>
          { inputTape := 0, workTapes := Fin.append (Complexity.LogProg.regMove r (-1)) Complexity.LogProg.dIdle,
            output := none, state := some (Complexity.LogProg.CSt.retR l s dir res a true) }

