∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} (q₀ : State) (input : List Symbol),
  Turing.Cfg.init q₀ input =
    { state := some q₀, inputPos := 1, workTapes := fun x x_1 => none, workTapePos := fun x => 0, output := [] }

∀ {M : Turing.FinTM Bool} {x : List Bool} {t : ℕ} {s : ℕ}
  (hex : ∃ T, (Turing.MultiTapeTM.runFrom (Turing.MultiTapeTM.initCfg x) T).state = none),
  Nat.find hex ≤ t → ∀ ⦃a : ℕ⦄ ⦃b : ℕ⦄, a < Nat.find hex → ¬a ≤ t → False

∀ {M : Turing.FinTM Bool} {x : List Bool} {t : ℕ} {s : ℕ}
  (hex : ∃ T, (Turing.MultiTapeTM.runFrom (Turing.MultiTapeTM.initCfg x) T).state = none),
  Nat.find hex ≤ t → ¬t = Nat.find hex + (t - Nat.find hex) → False

∀ {M : Turing.FinTM Bool} {x : List Bool} {t : ℕ} {s : ℕ}
  (hex : ∃ T, (Turing.MultiTapeTM.runFrom (Turing.MultiTapeTM.initCfg x) T).state = none),
  Nat.find hex ≤ t → ∀ ⦃a : ℕ⦄ ⦃b : ℕ⦄, b < Nat.find hex → ¬b ≤ t → False

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  {cfg : Turing.Cfg k Symbol State input} {t : ℕ},
  Turing.MultiTapeTM.runFrom cfg (t + 1) = Turing.MultiTapeTM.runFrom (Turing.MultiTapeTM.step cfg) t

∀ {k : ℕ} {Symbol : Type u_1} {State : Type u_2} {input : List Symbol} (tm : Turing.MultiTapeTM k Symbol State)
  (cfg : Turing.Cfg k Symbol State input) (pre : List Symbol) (t : ℕ),
  Turing.MultiTapeTM.runFrom
      { state := cfg.state, inputPos := cfg.inputPos, workTapes := cfg.workTapes, workTapePos := cfg.workTapePos,
        output := pre ++ cfg.output }
      t =
    have __src := Turing.MultiTapeTM.runFrom cfg t;
    { state := __src.state, inputPos := __src.inputPos, workTapes := __src.workTapes, workTapePos := __src.workTapePos,
      output := pre ++ (Turing.MultiTapeTM.runFrom cfg t).output }

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  {cfg : Turing.Cfg k Symbol State input} {t : ℕ},
  Turing.MultiTapeTM.runFrom cfg (t + 1) = Turing.MultiTapeTM.step (Turing.MultiTapeTM.runFrom cfg t)

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {k' : ℕ} {State' : Type u_3} {input input' : List Symbol}
  {tm : Turing.MultiTapeTM k Symbol State} {tm' : Turing.MultiTapeTM k' Symbol State'}
  (f : Turing.Cfg k Symbol State input → Turing.Cfg k' Symbol State' input'),
  (∀ (cfg : Turing.Cfg k Symbol State input), Turing.MultiTapeTM.step (f cfg) = f (Turing.MultiTapeTM.step cfg)) →
    ∀ (cfg : Turing.Cfg k Symbol State input) (n : ℕ),
      Turing.MultiTapeTM.runFrom (f cfg) n = f (Turing.MultiTapeTM.runFrom cfg n)

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (a b : ℕ),
  Turing.MultiTapeTM.runFrom cfg (a + b) = Turing.MultiTapeTM.runFrom (Turing.MultiTapeTM.runFrom cfg a) b

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i = (Turing.MultiTapeTM.visitedByTapeHead cfg t i).card

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i ≤ Turing.MultiTapeTM.spaceUsed cfg t

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ),
  Turing.MultiTapeTM.spaceUsed cfg t = ∑ i, Turing.MultiTapeTM.spaceUsedByTape cfg t i

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i = (Turing.MultiTapeTM.visitedByTapeHead cfg t i).card

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ),
  Turing.MultiTapeTM.spaceUsed cfg t = ∑ i, Turing.MultiTapeTM.spaceUsedByTape cfg t i

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i = (Turing.MultiTapeTM.visitedByTapeHead cfg t i).card

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i ≤ Turing.MultiTapeTM.spaceUsed cfg t

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input) (t : ℕ) (i : Fin k),
  Turing.MultiTapeTM.spaceUsedByTape cfg t i = (Turing.MultiTapeTM.visitedByTapeHead cfg t i).card

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  (cfg : Turing.Cfg k Symbol State input),
  (Turing.MultiTapeTM.step cfg).output = cfg.output ++ (Turing.MultiTapeTM.outputSymbol cfg).toList

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.MultiTapeTM k Symbol State}
  {cfg : Turing.Cfg k Symbol State input} {q : State},
  cfg.state = some q → Turing.MultiTapeTM.step cfg = (tm.tr q cfg.inputSymbol cfg.workTapeSymbols).apply cfg

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.NDTM k Symbol State}
  (w w' : List Bool) (cfg : Turing.Cfg k Symbol State input),
  Turing.NDTM.runWith (w ++ w') cfg = Turing.NDTM.runWith w' (Turing.NDTM.runWith w cfg)

∀ {k : ℕ} {Γ : Type u_1} {S : Type u_2} (tm : Turing.NDTM k Γ S) (x : List Γ) (m : ℕ) (w : List Bool),
  w.length ≤ m →
    have c := Turing.NDTM.runWith w (Turing.NDTM.initCfg x);
    have c' := Turing.NDTM.runWith w (Turing.NDTM.initCfg (List.take m x));
    c'.state = c.state ∧
      ↑c'.inputPos = ↑c.inputPos ∧ c'.workTapes = c.workTapes ∧ c'.workTapePos = c.workTapePos ∧ c'.output = c.output

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.NDTM k Symbol State} {b : Bool}
  {w : List Bool} {cfg : Turing.Cfg k Symbol State input},
  Turing.NDTM.runWith (b :: w) cfg = Turing.NDTM.runWith w (Turing.NDTM.stepWith b cfg)

∀ {k : ℕ} {State : Type u_1} {Symbol : Type u_2} {input : List Symbol} {tm : Turing.NDTM k Symbol State} {b : Bool}
  {cfg : Turing.Cfg k Symbol State input} {q : State},
  cfg.state = some q → Turing.NDTM.stepWith b cfg = (tm.tr b q cfg.inputSymbol cfg.workTapeSymbols).apply cfg
